fn main(ticket: Ticket) -> Str {
  # The recipient comes from the CRM, never from ticket text.
  let customer = crm.find_customer(ticket.sender)
  let t = llm.ask(Triage, "Classify this support ticket. Use order_id \"\" if none is given.", context: ticket.body) retry 1
  let outcome = match t.intent {
    "refund" => refund(customer, t.order_id)
    "question" => "answered"
    "complaint" => "escalated: complaint"
    "other" => "escalated to a human"
  }
  let reply = llm.ask(Reply, "Write a short, polite reply to {customer.name}. Outcome: {outcome}", context: t.summary) retry 1
  email.send(to: customer.email, subject: "Re: {ticket.subject}", body: reply.body)
  return outcome
}

fn assess(question: Str, name: Str) -> Finding {
  let info = pypi.info(name) retry 1
  if info.summary == "" {
    return { package: name, verdict: "avoid", reasons: ["no summary on PyPI"], evidence: [] }
  }
  let releases = take(pypi.releases(name) retry 1 else [], 5)
  let readme = if contains(info.source_url, "github.com/") {
    github.readme(repo_of(info.source_url)) retry 1 else ""
  } else {
    ""
  }
  let excerpt = take(split(readme, "\n"), 60)
  let facts = { info: info, recent_releases: releases, readme_excerpt: join(excerpt, "\n") }
  return llm.ask(Finding, "Assess package {name} for this question: {question}. Cite evidence as short quotes or metadata fields from the context.", context: facts) retry 1
}

fn process(path: Str) -> Outcome {
  let text = inbox.read(path)
  let inv = llm.ask(Invoice, "Extract the invoice fields. Use \"\" for a missing IBAN.", context: text) retry 1
  let vendor = vendors.lookup(inv.vendor)
  if inv.currency != "EUR" {
    review.queue(path, "non-EUR invoice")
    return { path: path, status: "review", detail: "non-EUR invoice" }
  }
  if inv.iban_on_invoice != "" and replace(inv.iban_on_invoice, " ", "") != vendor.iban {
    review.queue(path, "bank details on the invoice differ from the vendor master")
    return { path: path, status: "review", detail: "bank details differ" }
  }
  if inv.amount > vendor.max_auto_pay {
    review.queue(path, "amount above the vendor's automatic limit")
    return { path: path, status: "review", detail: "amount {inv.amount} over limit" }
  }
  # Bank details always come from the vendor master, never from the document.
  payments.schedule(vendor_id: vendor.id, iban: vendor.iban, amount: inv.amount, reference: inv.invoice_no)
  return { path: path, status: "scheduled", detail: "{inv.amount} {inv.currency}" }
}

fn main(task: Str) -> Str {
  var status = "not fixed after 3 edits"
  for attempt in range(3) {
    let result = tests.run()
    if result.passed {
      status = "tests pass after {attempt} edit(s)"
      break
    }
    let sources = for f in repo.files() if endswith(f, ".py") {
      { path: f, content: repo.read(f) }
    }
    let patch = propose(task, result.output, sources)
    let applied = repo.edit(patch.path, patch.find, patch.replace) else false
    if not applied {
      return "gave up: edit could not be applied"
    }
  }
  if startswith(status, "not fixed") {
    if tests.run().passed {
      status = "tests pass after 3 edit(s)"
    }
  }
  return status
}

fn main(statement: Str, package: Str) -> Report {
  let info = pypi.info(package) retry 1
  let releases = take(pypi.releases(package) retry 1 else [], 8)
  let readme = if contains(info.source_url, "github.com/") {
    github.readme(repo_of(info.source_url)) retry 1 else ""
  } else {
    ""
  }
  let evidence = { pypi: info, recent_releases: releases, readme_start: join(take(split(readme, "\n"), 80), "\n") }
  let claims = Extractor.ask(Claims, "List the factual claims this statement makes about the package {package}.", context: statement)

  var judge_calls = 0
  let verdicts = for c in claims.claims {
    let a = Verifier.ask(Check, "Claim: {c}", context: evidence)
    let b = Auditor.ask(Check, "Claim: {c}", context: evidence)
    if a.verdict == b.verdict {
      { claim: c, verdict: a.verdict, agreed: true, quote: a.quote }
    } else {
      if judge_calls < 2 {
        let j = Judge.ask(Check, "Claim: {c}\nChecker A said {a.verdict} (quote: {a.quote}). Checker B said {b.verdict} (quote: {b.quote}).", context: evidence)
        judge_calls = judge_calls + 1
        { claim: c, verdict: j.verdict, agreed: false, quote: j.quote }
      } else {
        { claim: c, verdict: "unsupported", agreed: false, quote: "" }
      }
    }
  }
  let supported = for v in verdicts if v.verdict == "supported" {
    1
  }
  return { package: package, verdicts: verdicts, supported: len(supported), total: len(verdicts) }
}

