fn main(statement: Str, package: Str) -> Report {
  let info = pypi.info(package) retry 1
  let releases = take(pypi.releases(package) retry 1 else [], 8)
  let readme = if contains(info.source_url, "github.com/") {
    github.readme(repo_of(info.source_url)) retry 1 else ""
  } else {
    ""
  }
  let evidence = { pypi: info, recent_releases: releases, readme_start: join(take(split(readme, "\n"), 80), "\n") }
  let claims = Extractor.ask(Claims, "List the factual claims this statement makes about the package {package}.", context: statement)

  let checks = for c in claims.claims {
    let verifier_check = Verifier.ask(Check, "Claim: {c}", context: evidence)
    let auditor_check = Auditor.ask(Check, "Claim: {c}", context: evidence)
    { claim: c, verifier: verifier_check, auditor: auditor_check }
  }

  let disagreed_claims = for check in checks if check.verifier.verdict != check.auditor.verdict {
    check.claim
  }
  let first_two_to_judge = take(disagreed_claims, 2)

  let verdicts = for check in checks {
    if check.verifier.verdict == check.auditor.verdict {
      { claim: check.claim, verdict: check.verifier.verdict, agreed: true, quote: check.verifier.quote }
    } else if check.claim in first_two_to_judge {
      let judge_result = Judge.ask(Check, "Claim: {check.claim}\nChecker A said {check.verifier.verdict} (quote: {check.verifier.quote}). Checker B said {check.auditor.verdict} (quote: {check.auditor.quote}).", context: evidence)
      { claim: check.claim, verdict: judge_result.verdict, agreed: false, quote: judge_result.quote }
    } else {
      { claim: check.claim, verdict: "unsupported", agreed: false, quote: "" }
    }
  }

  let supported = for v in verdicts if v.verdict == "supported" {
    1
  }
  return { package: package, verdicts: verdicts, supported: len(supported), total: len(verdicts) }
}

